import fs from 'fs';

// packages/alimentos-seo/dist/alimentos/<slug>/index.html  ->  dist/alimentos/<slug>/index.html
fs.cpSync('packages/alimentos-seo/dist/alimentos', 'dist/alimentos', { recursive: true });

// packages/alimentos-seo/dist/index.html (listing page, canonical = /alimentos) -> dist/alimentos/index.html
fs.copyFileSync('packages/alimentos-seo/dist/index.html', 'dist/alimentos/index.html');

// sitemap.xml / robots.txt generated by generate-sitemap.js -> published at site root
fs.copyFileSync('packages/alimentos-seo/dist/sitemap.xml', 'dist/sitemap.xml');
fs.copyFileSync('packages/alimentos-seo/dist/robots.txt', 'dist/robots.txt');

console.log('✅ SEO dist merged into dist/alimentos correctly (no double nesting)');
